CREATE TABLE "sales_portfolio" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE, "type" text NOT NULL, "name" text NOT NULL, "data" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_by" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "sales_portfolio_type_check" CHECK ("type" IN ('Corretor','Imobiliária','Site')));
CREATE INDEX "sales_portfolio_project_idx" ON "sales_portfolio" ("project_id"); CREATE INDEX "sales_portfolio_org_idx" ON "sales_portfolio" ("organization_id");
CREATE TABLE "sales_proposals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE, "number" integer NOT NULL, "origin_id" uuid REFERENCES "sales_portfolio"("id") ON DELETE SET NULL, "status" text NOT NULL, "data" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_by" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "sales_proposals_status_check" CHECK ("status" IN ('Em análise','Contraproposta','Recusada','Aceita')));
CREATE UNIQUE INDEX "sales_proposals_project_number_uidx" ON "sales_proposals" ("project_id","number"); CREATE INDEX "sales_proposals_org_idx" ON "sales_proposals" ("organization_id");
CREATE UNIQUE INDEX "sales_proposals_one_accepted_uidx" ON "sales_proposals" ("project_id") WHERE "status" = 'Aceita';
CREATE TABLE "service_providers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "document" text NOT NULL, "name" text NOT NULL, "data" jsonb DEFAULT '{}'::jsonb NOT NULL, "status" text DEFAULT 'active' NOT NULL, "created_by" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "service_providers_org_document_uidx" ON "service_providers" ("organization_id","document"); CREATE INDEX "service_providers_org_idx" ON "service_providers" ("organization_id");
CREATE TABLE "project_provider_assignments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE, "provider_id" uuid NOT NULL REFERENCES "service_providers"("id") ON DELETE RESTRICT, "data" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_by" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "project_provider_assignments_project_provider_uidx" ON "project_provider_assignments" ("project_id","provider_id"); CREATE INDEX "project_provider_assignments_org_idx" ON "project_provider_assignments" ("organization_id");
CREATE TABLE "distribution_snapshots" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "organization_id" uuid NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE, "data" jsonb NOT NULL, "calculated_by" text NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT, "calculated_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "distribution_snapshots_project_date_idx" ON "distribution_snapshots" ("project_id","calculated_at"); CREATE INDEX "distribution_snapshots_org_idx" ON "distribution_snapshots" ("organization_id");
